import { useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Link } from "react-router-dom";
import { createProject, listProjects, type ProjectPayload } from "@/api/projects";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Input, Label, Select, Textarea } from "@/components/ui/Input";
import { Alert, EmptyState, PageLoader } from "@/components/ui/Feedback";
import { extractErrorMessage } from "@/api/client";
import { formatCurrency, formatDate } from "@/lib/utils";

const blank = { name: "", description: "", role: "", required_skills: "", start_date: "", end_date: "", location: "", work_mode: "HYBRID", working_hours: 40, pay_rate: "", bill_rate: "", currency: "INR" };

export function VendorProjects() {
  const client = useQueryClient(); const [open, setOpen] = useState(false); const [form, setForm] = useState(blank); const [error, setError] = useState<string | null>(null);
  const { data: projects, isLoading } = useQuery({ queryKey: ["vendor-projects"], queryFn: listProjects });
  const mutation = useMutation({ mutationFn: createProject, onSuccess: () => { client.invalidateQueries({ queryKey: ["vendor-projects"] }); client.invalidateQueries({ queryKey: ["vendor-dashboard"] }); setForm(blank); setOpen(false); } });
  function submit(e: React.FormEvent) { e.preventDefault(); setError(null); const pay = Number(form.pay_rate), bill = Number(form.bill_rate); if (!pay || !bill || bill < pay) return setError("Enter positive rates; bill rate must be at least pay rate."); if (form.end_date && form.end_date < form.start_date) return setError("End date cannot be before start date."); mutation.mutate({ ...form, end_date: form.end_date || null, description: form.description || null, required_skills: form.required_skills || null, location: form.location || null, pay_rate: pay, bill_rate: bill } as ProjectPayload); }
  return <div className="space-y-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><h1 className="text-2xl font-bold text-ink-900">Projects &amp; Workforce</h1><p className="mt-1 text-sm text-ink-500">Define project terms, then assign your available contractors.</p></div><Button onClick={() => setOpen(!open)}>{open ? "Close" : "+ Create Project"}</Button></div>
  {open && <Card><CardHeader><CardTitle>New project</CardTitle></CardHeader><form onSubmit={submit}><CardContent className="space-y-4">{(error || mutation.isError) && <Alert variant="error">{error || extractErrorMessage(mutation.error)}</Alert>}<div className="grid grid-cols-1 gap-4 sm:grid-cols-2">{([['name','Project name *'],['role','Role *'],['required_skills','Required skills'],['location','Location']] as const).map(([key,label]) => <div key={key}><Label htmlFor={key}>{label}</Label><Input id={key} required={key === 'name' || key === 'role'} value={form[key]} onChange={e => setForm({...form,[key]:e.target.value})}/></div>)}<div><Label>Start date *</Label><Input type="date" required value={form.start_date} onChange={e=>setForm({...form,start_date:e.target.value})}/></div><div><Label>End date</Label><Input type="date" value={form.end_date} onChange={e=>setForm({...form,end_date:e.target.value})}/></div><div><Label>Work mode</Label><Select value={form.work_mode} onChange={e=>setForm({...form,work_mode:e.target.value})}><option>REMOTE</option><option>HYBRID</option><option>ONSITE</option></Select></div><div><Label>Working hours / week *</Label><Input type="number" min="1" max="168" value={form.working_hours} onChange={e=>setForm({...form,working_hours:Number(e.target.value)})}/></div><div><Label>Hourly pay rate *</Label><Input type="number" step=".01" required value={form.pay_rate} onChange={e=>setForm({...form,pay_rate:e.target.value})}/></div><div><Label>Hourly bill rate *</Label><Input type="number" step=".01" required value={form.bill_rate} onChange={e=>setForm({...form,bill_rate:e.target.value})}/></div></div><div><Label>Description</Label><Textarea rows={3} value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></div><div className="flex justify-end"><Button type="submit" isLoading={mutation.isPending}>Create Project</Button></div></CardContent></form></Card>}
  <Card>{isLoading ? <PageLoader/> : !projects?.length ? <EmptyState title="No projects yet" description="Create a project before making workforce assignments."/> : <div className="divide-y divide-ink-100">{projects.map(p=><div key={p.id} className="flex flex-wrap items-center justify-between gap-4 px-5 py-4"><div><p className="font-semibold text-ink-900">{p.name}</p><p className="text-sm text-ink-500">{p.role} · {p.work_mode}{p.location ? ` · ${p.location}` : ""}</p><p className="mt-1 text-xs text-ink-400">{formatDate(p.start_date)} → {formatDate(p.end_date)} · {p.assigned_contractors_count} assigned</p></div><div className="text-right"><p className="text-sm font-medium text-brand-700">{formatCurrency(p.pay_rate,p.currency)} pay / {formatCurrency(p.bill_rate,p.currency)} bill</p><Link to={`/vendor/assignments/new?project_id=${p.id}`}><Button size="sm" className="mt-2">Assign contractor</Button></Link></div></div>)}</div>}</Card></div>;
}
